  required Completer<void> betaRan,
  required Completer<void> alphaDone,
  required List<AssistantMessageEvent> alphaTurn,
}) {
  router.route('alpha', [
    () => _gated(alphaTurn, betaRan.future),
    () => _immediate(_textTurn('done')),
