    item: const TaskItem(name: 'alpha', task: 'monitor alpha repo'),
    index: 0,
    context: 'ctx',
  );
  final beta = executor.runSpawn(
    item: const TaskItem(name: 'beta', task: 'monitor beta repo'),
    index: 1,
    context: 'ctx',
  );
  return (alpha, beta, alphaDone.complete);
}

